import math
import hashlib

class BloomFilter:
    """
    A Bloom Filter implementation to test membership of items with a 
    specified false positive rate.

    The data structure uses a bit array to efficiently handle membership
    tests with a trade-off of allowing false positives. Optimal size of 
    the bit array and the number of hash functions are calculated based 
    on the expected number of items and desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than zero.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_num_hash_functions(self.size, expected_items)
        self.bit_array = [False] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_num_hash_functions(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((m / n) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        """Create a consistent hash for the item with a given seed."""
        hash_result = hashlib.sha256(f"{item}{seed}".encode()).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self.bit_array[index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            if not self.bit_array[index]:
                return False
        return True

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that provides an efficient way to 
    test membership of an item in a set, allowing for configurable
    false positive rates. The class uses its own bit array and basic
    hashing without relying on external libraries.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate size of the bit array (m) and number of hash functions (k)
        self.size = self.calculate_bit_array_size()
        self.num_hashes = self.calculate_number_of_hash_functions()

        # Create a bit array of the needed size initialized to False
        self.bit_array = [False] * self.size

    def calculate_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def calculate_number_of_hash_functions(self) -> int:
        """Calculate the optimal number of hash functions to use."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def hash(self, item: str, seed: int) -> int:
        """Produce a hash value for the item based on the given seed."""
        # Use hashlib for consistent hashing
        hash_object = hashlib.md5((str(seed) + item).encode())
        return int(hash_object.hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for seed in range(self.num_hashes):
            hashed_index = self.hash(item, seed)
            self.bit_array[hashed_index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for seed in range(self.num_hashes):
            hashed_index = self.hash(item, seed)
            if not self.bit_array[hashed_index]:
                return False
        return True
